import java.util.*;import net.bytebuddy.ByteBuddy;import net.bytebuddy.implementation.InvocationHandlerAdapter;import static net.bytebuddy.matcher.ElementMatchers.*;import com.garyzhangscm.cwms.outbound.service.*;import com.garyzhangscm.cwms.outbound.model.*;
public class BatchDeleteChecks {public static void main(String[] a)throws Exception {List<Long> ids=new ArrayList<>();ShipmentService s=new ByteBuddy().subclass(ShipmentService.class).method(named("findById").and(takesArguments(Long.class))).intercept(InvocationHandlerAdapter.of((o,m,args)->{Shipment x=new Shipment();x.setId((Long)args[0]);return x;})).method(named("removeShipment").and(takesArguments(Shipment.class))).intercept(InvocationHandlerAdapter.of((o,m,args)->{ids.add(((Shipment)args[0]).getId());return null;})).make().load(ShipmentService.class.getClassLoader()).getLoaded().getDeclaredConstructor().newInstance();s.delete("1,2");if(!ids.equals(Arrays.asList(1L,2L)))throw new AssertionError(ids);System.out.println("PASS: public batch-delete routes every ID through guarded removeShipment");}}
